        private static void TrangTriTheThongKe(Guna.UI2.WinForms.Guna2Panel card)
        {
            card.BorderRadius = 14;
            card.BorderColor = Color.FromArgb(229, 233, 243);
            card.BorderThickness = 1;
            card.FillColor = Color.White;
            card.ShadowDecoration.Enabled = true;
            card.ShadowDecoration.Depth = 6;
            card.ShadowDecoration.Color = Color.FromArgb(145, 125, 220);
        }

        private static void TrangTriNut(Guna.UI2.WinForms.Guna2Button button, Color fill, Color foreground, bool bordered)
        {
            button.Animated = true;
            button.Cursor = Cursors.Hand;
            button.BorderRadius = 9;
            button.FillColor = fill;
            button.ForeColor = foreground;
            button.BorderThickness = bordered ? 1 : 0;
            button.BorderColor = bordered ? ControlPaint.Light(foreground, 0.55F) : Color.Transparent;
            button.HoverState.FillColor = ControlPaint.Light(fill, 0.08F);
            button.HoverState.ForeColor = foreground;
        }

        private void ApplyResponsiveLayout()
        {
            int contentWidth = Math.Max(1080, ClientSize.Width - 50);
            pnlCards.Width = contentWidth;
            const int gap = 16;
            int cardWidth = (contentWidth - gap * 3) / 4;
            Guna.UI2.WinForms.Guna2Panel[] cards =
                { cardTongNhanVien, cardDangLamViec, cardTamNghi, cardTaiKhoanBiKhoa };
            for (int i = 0; i < cards.Length; i++)
            {
                cards[i].Location = new Point(i * (cardWidth + gap), 0);
                cards[i].Width = cardWidth;
            }

            int detailWidth = Math.Clamp(contentWidth * 29 / 100, 405, 456);
            int mainWidth = contentWidth - detailWidth - 14;
            pnlChart.Width = mainWidth;
            guna2Panel1.Width = mainWidth;
            pnlDanhSach.Width = mainWidth;
            pnlChiTiet.Location = new Point(25 + mainWidth + 14, pnlChart.Top);
            pnlChiTiet.Width = detailWidth;
            pnlChiTiet.Height = Math.Max(700, ClientSize.Height - pnlChiTiet.Top - 22);

            int actionX = 0;
            Guna.UI2.WinForms.Guna2Button[] actions =
                { btnThemNhanVien, btnXuatExcel, btnLamMoi };
            int[] widths = { 190, 160, 140 };
            for (int i = 0; i < actions.Length; i++)
            {
                actions[i].Location = new Point(actionX, 0);
                actions[i].Size = new Size(widths[i], 50);
                actionX += widths[i] + 8;
            }

            int filterGap = 10;
            int filterWidth = (mainWidth - 28 - filterGap * 3) / 4;
            txtTimKiem.Location = new Point(7, 46);
            txtTimKiem.Width = Math.Max(270, filterWidth);
            cboChucVu.Location = new Point(txtTimKiem.Right + filterGap, 46);
            cboChucVu.Width = filterWidth;
            label2.Left = cboChucVu.Left;
            cboTrangThai.Location = new Point(cboChucVu.Right + filterGap, 46);
            cboTrangThai.Width = filterWidth;
            label1.Left = cboTrangThai.Left;
            dtpNgayVaoLam.Location = new Point(cboTrangThai.Right + filterGap, 46);
            dtpNgayVaoLam.Width = mainWidth - dtpNgayVaoLam.Left - 8;
            label3.Left = dtpNgayVaoLam.Left;

            int legendTop = Math.Max(850, ClientSize.Height - 62);
            pnlDanhSach.Height = legendTop - pnlDanhSach.Top - 8;
            dgvNhanVien.Width = pnlDanhSach.ClientSize.Width - 11;
            dgvNhanVien.Height = Math.Max(320, pnlDanhSach.ClientSize.Height - 58);
            int pagerY = pnlDanhSach.ClientSize.Height - 42;
            foreach (Control control in new Control[] { btnTrangDau, btnTrangTruoc, btnPage1, btnPage2,
                         btnPage3, btnPage4, lblDots, btnLastPage, btnTrangSau, btnTrangCuoi,
                         label4, txtTrang, lblTongTrang, btnGo, lblPageInfo })
                control.Top = pagerY;
            lblPageInfo.Left = Math.Max(10, pnlDanhSach.ClientSize.Width - lblPageInfo.Width - 16);

            pnlChuThich.Location = new Point(25, legendTop);
            pnlChuThich.Width = mainWidth;

            // Các trường thông tin kết thúc tại dòng Vai trò (Y≈540). Khu vực thao tác luôn bắt đầu
            // bên dưới, không kéo nút theo đáy panel vì sẽ đè lên Trạng thái/Tên đăng nhập khi màn hình thấp.
            const int accountActionsTop = 558;
            const int permissionTop = 618;
            int detailInnerWidth = pnlChiTiet.ClientSize.Width - 32;
            int accountGap = 12;
            int accountButtonWidth = Math.Max(160, (detailInnerWidth - accountGap) / 2);
            btnDatLaiMatKhau.Location = new Point(16, accountActionsTop);
            btnDatLaiMatKhau.Size = new Size(accountButtonWidth, 50);
            btnKhoaTaiKhoan.Location = new Point(btnDatLaiMatKhau.Right + accountGap, accountActionsTop);
            btnKhoaTaiKhoan.Size = new Size(detailInnerWidth - accountButtonWidth - accountGap, 50);

            guna2Panel2.Location = new Point(16, permissionTop);
            guna2Panel2.Width = detailInnerWidth;

            // Địa chỉ dài chỉ chiếm vùng giá trị; không AutoSize/Anchor làm nhãn nở ngược sang trái.
            lblDiaChiChiTiet.Location = new Point(176, 326);
            lblDiaChiChiTiet.Size = new Size(Math.Max(180, pnlChiTiet.ClientSize.Width - 192), 52);
            lblDiaChiChiTiet.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;

            lblNotificationCount.Left = ClientSize.Width - 522;
            btnNotify.Left = lblNotificationCount.Left - 33;
            picAvatar.Left = ClientSize.Width - 478;
            lblUser.Left = picAvatar.Right + 14;
            lblRole.Left = lblUser.Left;
        }

